  "currentTexts": {
    "keyName": {
      "sourceKey": "Spell_ShyvanaQ_Name",
      "text": "焚焰打击"
    },
    "keySummary": {
      "sourceKey": "Spell_Shyvana_Q_Summary",
      "text": "希瓦娜的下次攻击会打击目标和周围区域。这个技能可以再次施放。在【魔龙形态】下，它提供一次额外的再次施放，对单体目标造成巨额伤害。"
    },
    "keyTooltip": {
      "sourceKey": "Spell_ShyvanaQ_Tooltip",
      "text": "<spellPassive>被动：</spellPassive>希瓦娜的攻击附带<magicDamage>@Calc_Max_Health_Damage@最大生命值的魔法伤害</magicDamage><OnHit>%i:OnHit%</OnHit>并使这个技能的冷却时间缩短@Cooldown_Reduction@秒。<br><br><spellActive>主动：</spellActive>希瓦娜的下次攻击会打击目标和周围区域，造成<physicalDamage>@Calc_Damage@物理伤害</physicalDamage>。在接下来的@RecastDuration@秒内，这个技能可以在一次攻击或短暂延迟后<recast>再次施放</recast>。<br><br><keywordMajor>魔龙形态：</keywordMajor>希瓦娜获得一次额外的<recast>再次施放</recast>，使她的下次攻击噬咬目标从而造成<trueDamage>@Calc_Dragon_Form_Damage@真实伤害</trueDamage>。"
    },
    "keyTooltipExtended": {
      "sourceKey": "Spell_ShyvanaQ_TooltipExtended",
      "text": "<spellPassive>被动：</spellPassive>希瓦娜的攻击附带<magicDamage>@Calc_Max_Health_Damage@最大生命值的魔法伤害</magicDamage><OnHit>%i:OnHit%</OnHit>并使这个技能的冷却时间缩短@Cooldown_Reduction@秒。<br><br><spellActive>主动：</spellActive>希瓦娜的下次攻击会打击目标周围的一个锥形区域，造成<physicalDamage>@Calc_Damage@物理伤害</physicalDamage>。在接下来的@RecastDuration@秒内，这个技能可以在一次攻击或短暂延迟后<recast>再次施放</recast>；<recast>再次施放</recast>会打击目标周围的一个圆形区域。<br><br><keywordMajor>魔龙形态：</keywordMajor>希瓦娜获得一次额外的<recast>再次施放</recast>，使她的下次攻击噬咬目标从而造成<trueDamage>@Calc_Dragon_Form_Damage@真实伤害</trueDamage>。"
    },
    "keyTooltipExtendedBelowLine": {
      "sourceKey": "Spell_ShyvanaQ_TooltipBelowLine",
      "text": "<rules>对野怪造成@Calc_Monster_Bonus@额外伤害。<br>最大生命值伤害不会影响建筑物，并且对抗非英雄单位时的最小值为@Calc_Max_Health_Monster_Minimum@并且最大值为@Calc_Max_Health_Monster_Maximum@。<br><keywordMajor>魔龙形态</keywordMajor>的最后一段<recast>再次施放</recast>不能产生暴击。</rules>"
    },
    "keyCost": {
      "sourceKey": "Spell_Shyvana_NoCost",
      "text": "无消耗"
    }
  }
